# -*- coding: utf-8 -*-
"""КОЛІР-ВІДНОШЕННЯ-2 (рядок 4650): одне джерело відношень кольору — класи тону, `tonal` і `echo` у `колір_річ.відношення` беруть
вердикт вікон `колір_відношення`. (1) Ланцюг імпорту: `колір_відношення` не імпортує `колір_річ`. (2) Пул руки 1 (4 сцени стенда), усі
пари речей різних слотів: вердикти за класами в трьох режимах — ДО (тверді межі кола, як до 4650: σ = 0, вікна ΔH* нульової ширини, без певності тону),
«ΔH*» (`певність=False` — так кличуть правила, що самі відбирають кольорові речі), «ΔH*+τ» (типовий виклик). (3) Приклади: светр ×
костюм (беж), помаранчі рядка 2860. (4) `-о N` — суд N образів стенда (сід 7, як `колір_нейтраль.py`), ДО → ПІСЛЯ: «правило:сила»
K-COL-02, K-ACC-01, K-COL-05, K-PAL-04/05/15, K-COMP-05, K-CRA-02. Запуск із джерела/: python3 проби/відношення_одне_4650.py [-о 300]"""
import ast, json, random, sys, collections as K; sys.path.insert(0, "."); sys.path.insert(0, "проби")
import pal_вердикт as ПВ, bridge as B, стенд_знімок as СЗ, colorspace as cs, колір_річ as КР, колір_відношення as КВ
ім = {n.names[0].name for n in ast.walk(ast.parse(open("колір_відношення.py", encoding="utf-8").read())) if isinstance(n, ast.Import)}
print("(1) колір_відношення імпортує колір_річ:", "колір_річ" in ім, "· колір_річ кличе вікна:", КР._ВІДНОШЕННЯ["same_hue"].__qualname__)
Б, РЕЖ, КЛ = (КВ.СІГМА_МЕЖІ, КВ.СІГМА_СВІТЛОТИ, КВ.ВІКНА_ΔH), ("ДО", "ΔH*", "ΔH*+τ"), tuple(КР._МІРА_ТОНУ) + ("tonal", "echo")
def режим(м): КВ.СІГМА_МЕЖІ, КВ.СІГМА_СВІТЛОТИ, КВ.ВІКНА_ΔH = (0.0, 0.0, {к: (0.0, в[1]) for к, в in Б[2].items()}) if м == "ДО" else Б
вх0, бачені, Л = json.load(open("стенд_вх.json", encoding="utf-8")), set(), K.Counter()
for назва in ("офіс·18°C", "дощ·ресторан·вечір", "весілля·гість", "спека·парк"):
    к = json.loads(B.виклик("запити", json.dumps(dict(вх0, сценарій=dict(СЗ.СЦЕНАРІЇ[назва]), випадок=назва), ensure_ascii=False)))["кандидати"]
    зі = {r["id"]: r for r in B.каталог_останнього_пакета()}
    рр = [(с, зі[r["id"]]) for с, xs in к.items() for r in xs if зі.get(r["id"]) and КР.межі_кольору(зі[r["id"]])]
    for i, (с1, x) in enumerate(рр):
        for с2, y in рр[i + 1:]:
            if с1 == с2 or (x["id"], y["id"]) in бачені: continue
            бачені |= {(x["id"], y["id"]), (y["id"], x["id"])}; вв = {}
            for м in РЕЖ: режим(м); вв[м] = [КР.відношення(x, y, кл, певність=м == "ΔH*+τ") for кл in КЛ]
            for j, кл in enumerate(КЛ): Л[(кл, вв["ДО"][j], вв["ΔH*"][j], вв["ΔH*+τ"][j])] += len({вв[м][j] for м in РЕЖ}) > 1
print("(2) пар %d; змінені вердикти — клас: ДО → ΔH* → ΔH*+τ" % (len(бачені) // 2))
for (кл, *в), n in sorted(Л.items()): n and print("    %-13s %-8s → %-8s → %-8s %7d" % (кл, *в, n))
for a, b in ([dict(lab=tuple(cs.hx(h))) for h in п] for п in (("#b79a83", "#b99b87"), ("#e7702f", "#f9842e"), ("#cc6a3b", "#f9842e"), ("#c46a36", "#df9962"))):
    вв = []
    for м in РЕЖ: режим(м); вв.append(КР.відношення(a, b, "same_hue", певність=м == "ΔH*+τ"))
    print("(3) %s × %s: Δколо %.1f, ΔH* %.1f — same_hue %s" % (cs.hex_з_lab(a["lab"]), cs.hex_з_lab(b["lab"]), КР.розкид_тону_на_колі(a, b)[0],
          КВ._дельта_h(КР.запис_кольору(a), КР.запис_кольору(b))[0], " → ".join(вв)))
N = int(sys.argv[sys.argv.index("-о") + 1]) if "-о" in sys.argv else 0
ПР, (вх, r, _, _) = ("K-COL-02", "K-ACC-01", "K-COL-05", "K-PAL-04", "K-PAL-05", "K-PAL-15", "K-COMP-05", "K-CRA-02"), ПВ.стенд(гілка=0, намір="statement")
к, rnd, С = r["кандидати"], random.Random(7), K.Counter()
for n in range(N):
    ід = [rnd.choice(к[с])["id"] for с in ("верх", "низ", "сукня", "верхній_шар", "взуття", "сумка", "шарф", "пояс", "сережки")
          if к.get(с) and с not in (("верх", "низ") if n % 2 else ("сукня",)) and rnd.random() < 0.7]
    зз = {м: (режим(м), sorted(z["правило"] + ":" + str(z.get("сила")) for z in ПВ.знахідки(вх, ід)[0] if z.get("правило") in ПР))[1] for м in ("ДО", "ПІСЛЯ")}
    С.update([(п, м) for м in зз for п in зз[м]] + [("образів зі зміною", "ПІСЛЯ")] * (зз["ДО"] != зз["ПІСЛЯ"]))
for п in sorted({п for п, _ in С}): print("(4) суд %d образів %-20s %s" % (N, п, " → ".join(str(С[(п, м)]) for м in ("ДО", "ПІСЛЯ"))))
